package com.astrocare.service;
import com.astrocare.dto.*; import com.astrocare.entity.*; import com.astrocare.exception.*; import com.astrocare.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.*;
@Service @RequiredArgsConstructor public class EmergencyService {private final EmergencyEventRepository events;private final AstronautRepository astronauts;private final UserRepository users; public EmergencyResponse sos(SosRequest r,String username){Astronaut a=astronauts.findByUserUsername(username).orElseThrow(()->new ForbiddenOperationException("Only astronaut accounts may dispatch SOS"));EmergencyEvent e=new EmergencyEvent();e.setAstronaut(a);e.setMission(a.getMission());e.setEventType(r.eventType());e.setSeverity(r.severity());e.setStatus(EmergencyStatus.ACTIVE);e.setDescription(r.description());e.setDeclaredBy(users.findByUsername(username).orElse(null));e.setDrill(false);e.setTriggeredAt(LocalDateTime.now(ZoneOffset.UTC));return EmergencyResponse.from(events.save(e));}}
